/**
 * Hand-maintained data-quality notes for cross-country comparability and
 * contested / self-reported series. Not generated by fetch-gdp.mjs.
 */

export type MeasureClass =
  | "nominal-gdp"
  | "nominal-gva"
  | "chain-volume"
  | "other";

export type SourceQuality = {
  sourceKey: "bea" | "statcan" | "abs" | "eurostat" | "worldbank" | "oecd";
  measureClass: MeasureClass;
  /** Short label shown in UI badges */
  badge: string;
  /** Whether country totals are roughly comparable as nominal USD levels */
  levelComparableToNominalUsd: boolean;
  summary: string;
};

/** Measure semantics by primary industry source. */
