export type AltEstimate = {
  label: string;
  value: string;
  note: string;
  url: string;
  yearLabel: string;
};

export type ContestedField = {
  field: "population" | "gdp" | "gdpPerCapita" | "ageStructure";
  severity: "high" | "medium";
  title: string;
  why: string;
  officialLabel: string;
  alternatives: AltEstimate[];
  counterpoints?: { label: string; note: string; url: string }[];
};

export type CountryQuality = {
  code: string;
  /** Non-comparable measure vs nominal USD GDP peers */
  measureWarning?: boolean;
  contested?: ContestedField[];
};

