export function qualityForCountry(
  code: string,
  sourceKey: string | undefined,
): {
  source: SourceQuality | null;
  country: CountryQuality;
} {
  const source = sourceKey ? (SOURCE_QUALITY[sourceKey] ?? null) : null;
  const country = COUNTRY_QUALITY[code] ?? { code };
  return {
    source,
    country: {
      ...country,
      measureWarning:
        country.measureWarning ??
        (source ? !source.levelComparableToNominalUsd : false),
    },
  };
}

export function contestedFor(
  code: string,
  field: ContestedField["field"],
): ContestedField | undefined {
  return COUNTRY_QUALITY[code]?.contested?.find((c) => c.field === field);
}
